247	    public static long gcd(long u, long v) {
248	        /* Thank you, Wikipedia. */
249	        /* But is this faster than just dividing on a modern
250	     * architecture? -Jan */
251	        long k = 0;
252	        if (u <= 0) {
253	            if (u == 0) return v;
254	            u = -u;
255	        }
256	        if (v <= 0) {
257	            if (v == 0) return u;
258	            v = -v;
259	        }
260	        long uv = u | v;
261	        for (; (uv & 1) == 0; uv >>>= 1) { /* While both u and v are even */
262	            k++;  /* Store their common power of 2 */
263	        }
264	        /* At this point either u or v (or both) is odd */
265	        u >>>= k;
266	        for (; (u & 1) == 0; u >>>= 1) {
267	        } /* Divide u by 2 until odd. */
268	        v >>>= k;
269	        for (; (v & 1) == 0; v >>>= 1) {
270	        } /* Divide v by 2 until odd. */
271	        while (true) {
272	            /* u and v are both odd */
273	            if (u >= v) {
274	                u = (u - v) >>> 1;
275	                if (u == 0) return (v << k);
276	                for (; (u & 1) == 0; u >>>= 1) {
277	                } /* Divide u by 2 until odd. */
278	            } else {
279	                /* u and v both odd, v > u */
280	                v = (v - u) >>> 1;
281	                for (; (v & 1) == 0; v >>>= 1) {
282	                } /* Divide v by 2 until odd. */
283	            }
284	        }
285	    }
