287	    public static long choose(long n, long k) {
288	        if (k > n / 2) k = n - k;
289	        if (k == 0) return 1;
290	        if (k == 1) return n;
291	        // k <= n/2
292	        // Will multiply (k) terms, n-k+1 through n-k+k
293	        // will divide by k terms, 1 through k
294	        // Note that if we divide after multiplying, it will
295	        // always be evenly divisible.
296	        // Proof: when we divide by k, we've multiplied by k consecutive integers,
297	        // at least one of which will be a multiple of k.
298	        long accum = 1;
299	        for (long j = 1; j <= k; j++) {
300	            long m = n - k + j;
301	            accum = accum * m;
302	            accum = accum / j;
303	        }
304	        return accum;
305	    }
