307	    public static long mod(long xi, long yi) {
308	        long ri = xi % yi;
309	        if (ri == 0) return 0;
310	
311	        if (yi > 0) {
312	            if (xi >= 0) return ri;
313	            return ri + yi;
314	        } else {
315	            if (xi >= 0) return ri + yi;
316	            return ri;
317	        }
318	    }
