320	    public static long pow(long x, long y) {
321	        long r = 1;
322	        while (y > 0) {
323	            if ((y & 1) != 0) {
324	                r *= x;
325	                y--;
326	            }
327	            x *= x;
328	            y >>>= 1;
329	        }
330	        return r;
331	    }
