   294	        // will divide by k terms, 1 through k
   295	        // Note that if we divide after multiplying, it will
   296	        // always be evenly divisible.
   297	        // Proof: when we divide by k, we've multiplied by k consecutive integers,
   298	        // at least one of which will be a multiple of k.
   299	        BigInteger accum = BigInteger.ONE;
   300	        for (BigInteger j = BigInteger.ONE; j.compareTo(k) <= 0; j = j.add(BigInteger.ONE)) {
